<?php require __DIR__.'/_guard.php';$sales=(float)db()->query("SELECT COALESCE(SUM(grand_total),0) FROM orders WHERE order_status<>'cancelled'")->fetchColumn();$cost=(float)db()->query("SELECT COALESCE(SUM(oi.quantity*p.cost_price),0) FROM order_items oi JOIN products p ON p.id=oi.product_id JOIN orders o ON o.id=oi.order_id WHERE o.order_status<>'cancelled'")->fetchColumn();$exp=(float)db()->query('SELECT COALESCE(SUM(amount),0) FROM expenses')->fetchColumn();$profit=$sales-$cost-$exp;?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/css/admin.css"></head><body><main><a href="/admin/">← Dashboard</a><h1>Profit & Loss</h1><div class="cards"><article>Sales<strong><?=money($sales)?></strong></article><article>Estimated cost of goods<strong><?=money($cost)?></strong></article><article>Expenses<strong><?=money($exp)?></strong></article><article>Estimated net profit<strong><?=money($profit)?></strong></article></div><p>Profit is an estimate based on current product cost prices. Historical cost snapshots and tax rules should be configured for formal accounting.</p><a href="/admin/export-orders.php">Export orders CSV</a></main></body></html>